    }

    // do-while runs at least once
    int attempts = 0;
    do
    {
        ++attempts;
        std::cout << "Attempt " << attempts << '\n';
    } while (attempts < 2);

    // Range-based for loop (C++11)
    std::vector<std::string> languages = { "C++", "C#", "SQL" };
    for (const auto& language : languages)
        std::cout << language << '\n';

    // Modify elements by reference
    std::array<int, 4> numbers = { 1, 2, 3, 4 };
    for (int& n : numbers)
        n *= 10;

    for (int n : numbers)
        std::cout << n << ' ';
    std::cout << '\n';

