#include <iostream>
#include <memory>

int main()
{
    const int size = 5;

    // Allocate memory on the heap
    int* numbers = new int[size];

    for (int i = 0; i < size; ++i)
        numbers[i] = i * i;

    int* cursor = numbers;
    for (int i = 0; i < size; ++i)
        std::cout << *(cursor + i) << ' ';

    std::cout << "\nAddress: " << static_cast<void*>(numbers) << '\n';

    // Free the memory
    delete[] numbers;
    numbers = nullptr;

    // The same idea, but exception-safe
    auto safe = std::make_unique<int[]>(size);
    safe[0] = 42;
    std::cout << "Safe: " << safe[0] << '\n';

    return 0;
}

