class Resource
{
public:
    explicit Resource(std::string name) : name_(std::move(name))
    {
        std::cout << "Created " << name_ << '\n';
    }
    ~Resource() { std::cout << "Destroyed " << name_ << '\n'; }

    void use() const { std::cout << "Using " << name_ << '\n'; }

private:
    std::string name_;
};

int main()
{
    auto exclusive = std::make_unique<Resource>("Unique");
    exclusive->use();

    auto shared = std::make_shared<Resource>("Shared");
    {
        auto copy = shared;           // ref count = 2
        copy->use();
        std::cout << "Refs: " << shared.use_count() << '\n';
    }

    std::cout << "Refs: " << shared.use_count() << '\n';
    return 0;
}

