from functools import wraps
from typing import Callable

# Default and keyword arguments
def greet(name: str, greeting: str = "Hello") -> str:
    return f"{greeting}, {name}!"

# Type hints and a default of None
def power(base: float, exponent: int = 2) -> float:
    return base ** exponent

# *args and **kwargs
def summarize(*numbers: int, **options: object) -> dict:
    return {
        "count": len(numbers),
        "total": sum(numbers),
        "options": options,
    }

# Multiple return values (a tuple)
def min_max(values: list[int]) -> tuple[int, int]:
    return min(values), max(values)

# Keyword-only arguments (after *)
def connect(host: str, *, port: int = 5432, timeout: int = 30) -> str:
    return f"{host}:{port} (timeout {timeout}s)"

# Decorator with wraps
def logged(func: Callable) -> Callable:
    @wraps(func)
    def wrapper(*args, **kwargs):
        print(f"Calling {func.__name__}")
        return func(*args, **kwargs)

    return wrapper

@logged
def add(a: int, b: int) -> int:
    return a + b

print(greet("Ali"))
print(greet("Sara", greeting="Welcome"))
print(power(3), summarize(1, 2, 3, verbose=True))
print(min_max([4, 9, 1, 12]))
print(connect("localhost", port=3306))
print(add(2, 3))

public class Basics {
    public static void main(String[] args) {
        // Primitive types
        int age = 25;
        double height = 1.78;
        char initial = 'A';
        boolean isDeveloper = true;
        final double PI = 3.14159;

        // Reference type
        String name = "Ali";

        // Local variable type inference (Java 10+)
        var city = "Amman";
        var scores = new int[] { 90, 85, 77 };

        // Output
        System.out.println("Name: " + name + ", Age: " + age);
        System.out.printf("Height: %.2f m | City: %s%n", height, city);
        System.out.println("Developer: " + isDeveloper + " | Pi: " + PI);
        System.out.printf("Scores: %d items%n", scores.length);

        // Reading input
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        System.out.print("Favourite language: ");
        String language = scanner.nextLine();
        System.out.printf("You picked %s (letter %c)%n", language, initial);

        // Safe conversion
        try {
            int parsed = Integer.parseInt("42");
            System.out.println("Parsed: " + parsed * 2);
        } catch (NumberFormatException e) {
            System.out.println("Not a number");
        }
    }
}

public class ControlFlow {
    public static void main(String[] args) {
        int score = 87;

        // if / else if / else
        if (score >= 90) {
            System.out.println("Excellent");
        } else if (score >= 75) {
            System.out.println("Good");
        } else {
            System.out.println("Needs improvement");
        }

        // Ternary
        String status = score >= 50 ? "Pass" : "Fail";

        // Classic switch (multiple labels + break)
        char grade;
        switch (score / 10) {
            case 9:
            case 10:
                grade = 'A';
                break;
            case 8:
                grade = 'B';
                break;
            default:
                grade = 'C';
        }

        // switch expression with arrow labels (Java 14+)
        String message = switch (grade) {
            case 'A' -> "Outstanding work!";
            case 'B' -> "Well done!";
            default -> "Keep practising.";
        };

        // Pattern matching for instanceof (Java 16+)
        Object value = "SyntaxHub";
        if (value instanceof String text && text.length() > 5) {
            System.out.println(text.toUpperCase());
        }

        System.out.println(status + " — Grade " + grade + ": " + message);
    }
}

import java.util.*;

public class Loops {
    public static void main(String[] args) {
        // Classic for
        for (int i = 0; i < 5; i++) {
            if (i == 2) continue;
            System.out.print(i + " ");
        }
        System.out.println();

        // while
        int countdown = 3;
        while (countdown > 0) {
            System.out.println("T-minus " + countdown);
            countdown--;
        }

        // do-while runs at least once
        int attempts = 0;
        do {
            attempts++;
            System.out.println("Attempt " + attempts);
        } while (attempts < 2);

        // Enhanced for (for-each)
        List<String> languages = List.of("Java", "C#", "SQL");
        for (String language : languages) {
            System.out.println(language);
        }

        // Labelled break exits the outer loop
        outer:
        for (int row = 0; row < 3; row++) {
            for (int col = 0; col < 3; col++) {
                if (row == 1 && col == 1) break outer;
                System.out.printf("(%d,%d) ", row, col);
            }
        }
        System.out.println();

        // Iterate a Map
        Map<String, Integer> prices = new HashMap<>(Map.of("Keyboard", 50, "Monitor", 199));
        for (Map.Entry<String, Integer> entry : prices.entrySet()) {
            System.out.println(entry.getKey() + ": $" + entry.getValue());
        }
    }
}

import java.util.Arrays;

public class Methods {
    // Static method with return value
    static int add(int a, int b) {
        return a + b;
    }

    // Overloading: same name, different parameter types
    static double add(double a, double b) {
        return a + b;
    }

    // Varargs: zero or more arguments
    static int sum(int... values) {
        return Arrays.stream(values).sum();
    }

    // Generic method
    static <T> T firstOrNull(T[] items) {
        return items.length > 0 ? items[0] : null;
    }

    // Record: immutable data carrier with accessors (Java 16+)
    record Range(int min, int max) {}

    static Range minMax(int[] values) {
        int min = Arrays.stream(values).min().orElse(0);
        int max = Arrays.stream(values).max().orElse(0);
        return new Range(min, max);
    }

    // Instance method
    String greet(String name) {
        return "Hello, " + name + "!";
    }

    public static void main(String[] args) {
        System.out.println(add(2, 3));
        System.out.println(add(1.5, 2.25));
        System.out.println(sum(1, 2, 3, 4));
        System.out.println(firstOrNull(new String[] { "Java", "C#" }));

        Range range = minMax(new int[] { 4, 9, 1, 12 });
        System.out.println(range.min() + " – " + range.max());

        Methods methods = new Methods();
        System.out.println(methods.greet("Ali"));
    }
}

import java.util.*;

public class CollectionsDemo {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Ali", "Sara", "Omar", "Sara"));
        names.add("Lina");
        Collections.sort(names);

        Set<String> unique = new HashSet<>(names);

        Map<String, Integer> counts = new HashMap<>();
        for (String name : names) {
            counts.merge(name, 1, Integer::sum);
        }

        System.out.println("Sorted list: " + names);
        System.out.println("Unique: " + unique.size());
        System.out.println("Counts: " + counts);

        names.removeIf(n -> n.startsWith("S"));
        System.out.println("After filter: " + names);
    }
}

import java.util.*;
import java.util.stream.*;

record Employee(String name, String dept, double salary) {}

public class StreamsDemo {
    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Ali", "Engineering", 5200),
            new Employee("Sara", "Engineering", 6100),
            new Employee("Omar", "Sales", 3800),
            new Employee("Lina", "Sales", 4500),
            new Employee("Noor", "HR", 3200)
        );

        Map<String, List<String>> byDept = staff.stream()
            .collect(Collectors.groupingBy(
                Employee::dept,
                Collectors.mapping(Employee::name, Collectors.toList())));

        double engineeringAverage = staff.stream()
            .filter(e -> e.dept().equals("Engineering"))
            .mapToDouble(Employee::salary)
            .average()
            .orElse(0);

        List<String> topEarners = staff.stream()
            .filter(e -> e.salary() > 4000)
            .sorted(Comparator.comparingDouble(Employee::salary).reversed())
            .map(Employee::name)
            .toList();

        System.out.println(byDept);
        System.out.printf("Engineering avg: %.2f%n", engineeringAverage);
        System.out.println("Top earners: " + topEarners);
    }
}

interface Describable {
    String describe();

    default String label() {
        return "[shape] " + describe();
    }
}

abstract class Shape implements Describable {
    protected final String name;

    protected Shape(String name) {
        this.name = name;
    }

    public abstract double area();

    @Override
    public String describe() {
        return String.format("%s with area %.2f", name, area());
    }
}

class Circle extends Shape {
    private final double radius;

    Circle(double radius) {
        super("Circle");
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }
}

class Rectangle extends Shape {
    private final double width, height;

    Rectangle(double width, double height) {
        super("Rectangle");
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }
}

public class Main {
    public static void main(String[] args) {
        java.util.List<Shape> shapes = java.util.List.of(new Circle(2), new Rectangle(3, 4));
        shapes.forEach(s -> System.out.println(s.label()));
    }
}

.button {
  /* Custom properties act as function arguments */
  --accent: #58a6ff;
  --pad-x: 1rem;

  /* calc() mixes units */
  width: calc(100% - 2 * var(--pad-x));
  padding: calc(var(--pad-x) / 2) var(--pad-x);

  /* clamp(min, preferred, max) = fluid sizing */
  font-size: clamp(0.85rem, 1.6vw, 1rem);

  /* min() / max() pick a bound */
  max-width: min(420px, 90vw);
  min-height: max(44px, 5vh);

  /* Modern color functions */
  color: rgb(255 255 255 / 0.92);
  background: hsl(from var(--accent) h s l / 0.15);
  border: 1px solid color-mix(in srgb, var(--accent) 45%, transparent);

  /* Fallback syntax for custom properties */
  border-radius: var(--radius, 10px);

  /* Transform functions */
  transform: translateY(0) scale(1);
  transition: transform 180ms ease, background-color 180ms ease;
}

.button:hover {
  transform: translateY(-2px) scale(1.01);
  background: color-mix(in srgb, var(--accent) 22%, transparent);
}

